package com.example.smartpantrymanager;
import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.recyclerview.widget.*;import java.util.*;
public class RecipeAdapter extends RecyclerView.Adapter<RecipeAdapter.VH>{public interface Listener{void click(Recipe r);}private List<Recipe> list;private Listener listener;public RecipeAdapter(List<Recipe> l,Listener x){list=l;listener=x;}@NonNull public VH onCreateViewHolder(@NonNull ViewGroup p,int t){return new VH(LayoutInflater.from(p.getContext()).inflate(R.layout.item_recipe,p,false));}public void onBindViewHolder(@NonNull VH h,int pos){Recipe r=list.get(pos);h.name.setText(r.getName());h.itemView.setOnClickListener(v->listener.click(r));}public int getItemCount(){return list.size();}static class VH extends RecyclerView.ViewHolder{TextView name;VH(View v){super(v);name=v.findViewById(R.id.txtRecipeName);}}}
